2	 * Soft-delete filtering.
3	 *
4	 * Archived rows stay in the table and disappear from every default read. The
5	 * cases below pin both halves of that: an archived issue is invisible unless
6	 * `includeArchived` is set, and archiving a project cascades to its issues.
7	 */
8	import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
9	
