15	import * as issueService from "@/server/services/issue-service";
16	import * as projectService from "@/server/services/project-service";
17	import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
18	import type { Tenant } from "./_support/fixtures";
19	import type { Issue } from "@/types/issue";
20	
21	let cleanup: () => void;
22	let tenant: Tenant;
23	let live: Issue;
24	let archived: Issue;
25	
26	beforeAll(async () => {
27	  cleanup = await useTemporaryDatabase();
28	  tenant = await createTenant("softdelete");
29	
30	  live = await issueService.createIssue(
31	    tenant.actors.member,
32	    issueInput(tenant.org.id, tenant.project.id, { title: "Still open" }),
33	  );
34	
35	  const doomed = await issueService.createIssue(
36	    tenant.actors.member,
37	    issueInput(tenant.org.id, tenant.project.id, { title: "Archived away" }),
38	  );
39	
40	  archived = await issueService.archiveIssue(
41	    tenant.actors.member,
42	    tenant.org.id,
43	    doomed.id,
44	  );
45	});
46	
47	afterAll(() => {
48	  cleanup();
49	});
50	
51	describe("archived issues", () => {
52	  it("marks the row rather than deleting it", async () => {
