/**
 * Rules for the sub-issue tree: it never loops and never nests deeper than
 * `MAX_SUB_ISSUE_DEPTH`. The guards are pure — the service works out the
 * lineage and the depth, and these decide whether they are acceptable.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";

/** A parent link that would loop the tree or nest it too deep. Maps to `conflict`. */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot sit under itself or under one of its sub-issues.`
        : `Issue ${issueId} cannot nest deeper than level ${MAX_SUB_ISSUE_DEPTH}.`,
    );
    this.name = "IssueHierarchyError";
  }
}

/**
 * `lineage` is the candidate parent followed by its ancestors. If the issue
 * appears in it, the issue would become its own ancestor.
 */
export function assertNoCycle(
  issueId: string,
  lineage: readonly { readonly id: string }[],
): void {
  if (lineage.some((node) => node.id === issueId)) {
    throw new IssueHierarchyError(issueId, "cycle");
  }
}

/** `deepestLevel` is where the deepest issue of the placed tree would land; a root is level 0. */
export function assertWithinDepth(issueId: string, deepestLevel: number): void {
  if (deepestLevel > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}

