/** Re-points one issue at a new parent, or at none. The hierarchy rules live in the service. */
export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/** Direct sub-issues of `parentId`, oldest first: creation time, then issue number. */
export async function listChildIssues(
  orgId: OrgId,
  parentId: IssueId,
  scope: ArchiveScope = {},
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.parentId, parentId),
          livePredicate(issues.archivedAt, scope),
        ),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  return toIssuesWithLabels(orgId, rows);
}

/**
 * Every issue below `issueId`, at any depth and in any archive state, nearest
 * level first. One query per level, so the cost follows the tree's height
 * rather than its size. Rows already seen are skipped, which keeps a corrupt
 * loop finite.
 */
export async function listDescendantIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const seen = new Set<string>([issueId]);
  const found: IssueRow[] = [];
  let frontier: string[] = [issueId];

  while (frontier.length > 0) {
    const level = getDb()
      .select()
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.parentId, frontier),
        ),
      )
      .all();

    frontier = [];
    for (const row of level) {
      if (seen.has(row.id)) continue;
      seen.add(row.id);
      found.push(row);
      frontier.push(row.id);
    }
  }

  return toIssuesWithLabels(orgId, found);
}

/** Archives the listed issues that are still live, in one statement. Archived rows are left untouched. */
export async function archiveIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.id, [...issueIds]),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning()
    .all();

  return rows.map((row) => toIssue(row));
}

