/**
 * Archives an issue together with every live issue below it, at any depth.
 * Each one is announced with its own `issue.archived`. The parent is never
 * touched, but archiving the last open sub-issue may tell the parent's assignee.
 */
export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  // Archived rows below stay as they are; only the live ones go with the parent.
  const belowIds = (await issueRepo.listDescendantIssues(orgId, issueId))
    .filter(isLive)
    .map((descendant) => descendant.id);

  const archived = await issueRepo.archiveIssue(orgId, issueId);
  const cascaded = await issueRepo.archiveIssuesByIds(orgId, belowIds);

  for (const row of [archived, ...cascaded]) {
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: row.id,
      projectId: row.projectId,
    });
  }

  if (stoppedBeingOpen(issue, archived)) {
    await announceSubIssuesCompleted(actor, archived);
  }

  return archived;
}

