/**
 * The parent must be a live issue of the same project. `findIssueById` is
 * already scoped to `orgId`, so another workspace's issue reads as not found.
 */
async function requireParentIssue(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = requireFound(
    await issueRepo.findIssueById(orgId, parentId),
    "Issue",
    parentId,
  );
  if (parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/** `start` followed by its ancestors, nearest first, up to a root. */
async function lineageOf(orgId: OrgId, start: Issue): Promise<readonly Issue[]> {
  const lineage: Issue[] = [start];
  const seen = new Set<string>([start.id]);
  let current = start;

  while (current.parentId !== null) {
    const next = await issueRepo.findIssueById(orgId, current.parentId);
    if (next === null || seen.has(next.id)) break;
    seen.add(next.id);
    lineage.push(next);
    current = next;
  }

  return lineage;
}

/**
 * How many levels the deepest of `descendants` sits below `rootId`.
 * `descendants` arrives nearest level first, as the repository returns it.
 */
function heightBelow(rootId: IssueId, descendants: readonly Issue[]): number {
  const levelOf = new Map<string, number>([[rootId, 0]]);
  let height = 0;

  for (const node of descendants) {
    const above = node.parentId === null ? undefined : levelOf.get(node.parentId);
    if (above === undefined) continue;
    levelOf.set(node.id, above + 1);
    height = Math.max(height, above + 1);
  }

  return height;
}

/** Open means live and not in a closed status. */
function isOpenIssue(issue: Issue): boolean {
  return (
    issue.archivedAt === null && !CLOSED_ISSUE_STATUSES.includes(issue.status)
  );
}

/** True when an issue was open and no longer is: the moment it counts as completed. */
function stoppedBeingOpen(before: Issue, after: Issue): boolean {
  return isOpenIssue(before) && !isOpenIssue(after);
}

/**
 * Tells the assignee of `closed`'s direct parent that its sub-issues are done,
 * once nothing below that parent is still open. Runs after the write that
 * closed `closed`, so it sees the new state. The envelope carries the actor,
 * so the fan-out never tells them about their own change.
 */
async function announceSubIssuesCompleted(actor: Actor, closed: Issue): Promise<void> {
  if (closed.parentId === null) return;

  const parent = await issueRepo.findIssueById(closed.orgId, closed.parentId);
  if (parent === null || parent.archivedAt !== null) return;
  if (parent.assigneeId === null) return;

  const below = await issueRepo.listDescendantIssues(closed.orgId, parent.id);
  if (below.some((descendant) => isOpenIssue(descendant))) return;

  await emit("issue.sub_issues_completed", {
    ...actorEnvelope(actor),
    issueId: parent.id,
    projectId: parent.projectId,
    assigneeId: parent.assigneeId,
  });
}

