  const parent = await issueRepo.findIssueById(closed.orgId, closed.parentId);
  if (parent === null || parent.archivedAt !== null) return;
  if (parent.assigneeId === null) return;

  const below = await issueRepo.listDescendantIssues(closed.orgId, parent.id);
  if (below.some((descendant) => isOpenIssue(descendant))) return;

  await emit("issue.sub_issues_completed", {
    ...actorEnvelope(actor),
    issueId: parent.id,
    projectId: parent.projectId,
    assigneeId: parent.assigneeId,
  });
}

