 * `descendants` arrives nearest level first, as the repository returns it.
 */
function heightBelow(rootId: IssueId, descendants: readonly Issue[]): number {
  const levelOf = new Map<string, number>([[rootId, 0]]);
  let height = 0;

  for (const node of descendants) {
    const above = node.parentId === null ? undefined : levelOf.get(node.parentId);
    if (above === undefined) continue;
    levelOf.set(node.id, above + 1);
    height = Math.max(height, above + 1);
  }

  return height;
}

