/**
 * Sub-issues: placing and moving under a parent, the cycle and depth rules,
 * listing and roll-up, archiving with the tree, and the completion notice.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Issue, IssueStatus } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("subissues", "growth");
  other = await createTenant("subissues-other", "growth");
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

/** Creates an issue in the tenant's platform project, optionally under a parent. */
function makeIssue(
  title: string,
  parentId: IssueId | null = null,
  assigneeId: UserId | null = null,
): Promise<Issue> {
  return issueService.createIssue(tenant.actors.member, {
    ...issueInput(tenant.org.id, tenant.project.id, { title, assigneeId }),
    parentId,
  });
}

function setParent(
  issueId: IssueId,
  parentId: IssueId | null,
  actor = tenant.actors.member,
): Promise<Issue> {
  return issueService.setIssueParent(actor, {
    orgId: tenant.org.id,
    issueId,
    parentId,
  });
}

function changeStatus(issueId: IssueId, status: IssueStatus): Promise<Issue> {
  return issueService.changeIssueStatus(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId,
    status,
  });
}

/** Settles a call that must be refused and returns the hierarchy reason. */
async function refusedReason(attempt: Promise<unknown>): Promise<string> {
  const error: unknown = await attempt.then(
    () => undefined,
    (caught: unknown) => caught,
  );
  expect(error).toBeInstanceOf(IssueHierarchyError);
  return (error as IssueHierarchyError).reason;
}

/** How many `sub_issues_completed` notices `recipient` got about `parent`. */
async function noticesFor(recipient: UserId, parent: Issue): Promise<number> {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: recipient,
    unreadOnly: false,
    kind: ["sub_issues_completed"],
    limit: 100,
    cursor: null,
  });
  return page.items.filter((item) => item.href === `/issues/${parent.id}`).length;
}

describe("placing an issue under a parent", () => {
  it("places a sub-issue and announces the change as issue.updated", async () => {
    const parent = await makeIssue("Placed parent");
    const child = await makeIssue("Placed child");
    const updated = capture("issue.updated");

    const after = await setParent(child.id, parent.id);

    expect(after.parentId).toBe(parent.id);
    expect(updated).toHaveLength(1);
    expect(updated[0]).toMatchObject({
      issueId: child.id,
      changedFields: ["parentId"],
    });
  });

  it("moves a sub-issue to another parent and makes it a root again", async () => {
    const first = await makeIssue("Move from");
    const second = await makeIssue("Move to");
    const child = await makeIssue("Movable", first.id);

    const moved = await setParent(child.id, second.id);
    expect(moved.parentId).toBe(second.id);

    const root = await setParent(child.id, null);
    expect(root.parentId).toBeNull();
  });

  it("announces nothing when the parent is already the one given", async () => {
    const parent = await makeIssue("Same parent");
    const child = await makeIssue("Already there", parent.id);
    const updated = capture("issue.updated");

    const after = await setParent(child.id, parent.id);

    expect(after.parentId).toBe(parent.id);
    expect(updated).toHaveLength(0);
  });

  it("refuses a parent from another project as not found", async () => {
    const mobile = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Mobile",
      slug: "mobile",
      key: "MOB",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const foreign = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, mobile.id, { title: "Mobile parent" }),
    );
    const child = await makeIssue("Platform child");

    await expect(setParent(child.id, foreign.id)).rejects.toMatchObject({
      code: "not_found",
    });
  });

  it("refuses a parent from another workspace as not found", async () => {
    const foreign = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Other workspace parent" }),
    );
    const child = await makeIssue("Local child");

    await expect(setParent(child.id, foreign.id)).rejects.toMatchObject({
      code: "not_found",
    });
  });

  it("refuses an archived parent as already archived", async () => {
    const parent = await makeIssue("Archived parent");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id);
    const child = await makeIssue("Child of archived");

    await expect(setParent(child.id, parent.id)).rejects.toBeInstanceOf(
      AlreadyArchivedError,
    );
  });

  it("refuses to move an archived issue", async () => {
    const parent = await makeIssue("Live parent");
    const child = await makeIssue("Archived child");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    await expect(setParent(child.id, parent.id)).rejects.toBeInstanceOf(
      AlreadyArchivedError,
    );
  });

  it("refuses a move across workspaces with TenantScopeError", async () => {
    const child = await makeIssue("Tenant guarded");

    await expect(
      issueService.setIssueParent(other.actors.owner, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("refuses an actor who may not update the issue", async () => {
    const parent = await makeIssue("Viewer parent");
    const child = await makeIssue("Viewer child");

    await expect(
      setParent(child.id, parent.id, tenant.actors.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
});

describe("the tree never loops or nests too deep", () => {
  it("refuses a parent that is the issue itself or one of its sub-issues", async () => {
    const top = await makeIssue("Loop top");
    const middle = await makeIssue("Loop middle", top.id);
    const bottom = await makeIssue("Loop bottom", middle.id);

    expect(await refusedReason(setParent(top.id, top.id))).toBe("cycle");
    expect(await refusedReason(setParent(top.id, bottom.id))).toBe("cycle");
  });

  it("refuses a move that would push the deepest sub-issue past level 3, changing nothing", async () => {
    // Chain: a (0) -> b (1) -> c (2) -> d (3).
    const a = await makeIssue("Depth a");
    const b = await makeIssue("Depth b", a.id);
    const c = await makeIssue("Depth c", b.id);
    const d = await makeIssue("Depth d", c.id);
    const loose = await makeIssue("Loose");

    expect(await refusedReason(setParent(loose.id, d.id))).toBe("too_deep");
    expect((await issueRepo.findIssueById(tenant.org.id, loose.id))?.parentId).toBeNull();

    // A move is judged by its deepest descendant: a root with two levels
    // below it cannot go under level 1 …
    const root = await makeIssue("Subtree root");
    const kid = await makeIssue("Subtree kid", root.id);
    await makeIssue("Subtree grandkid", kid.id);

    expect(await refusedReason(setParent(root.id, b.id))).toBe("too_deep");
    expect((await issueRepo.findIssueById(tenant.org.id, root.id))?.parentId).toBeNull();

    // … but it fits under level 0.
    expect((await setParent(root.id, a.id)).parentId).toBe(a.id);
  });

  it("refuses creating a sub-issue below level 3 and creates nothing", async () => {
    const top = await makeIssue("Create depth 0");
    const one = await makeIssue("Create depth 1", top.id);
    const two = await makeIssue("Create depth 2", one.id);
    const three = await makeIssue("Create depth 3", two.id);

    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id, {
      includeArchived: true,
    });
    const created = capture("issue.created");

    const attempt = issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, tenant.project.id, { title: "Too deep" }),
      parentId: three.id,
    });

    expect(await refusedReason(attempt)).toBe("too_deep");
    expect(
      await issueRepo.countIssues(tenant.org.id, tenant.project.id, {
        includeArchived: true,
      }),
    ).toBe(before);
    expect(created).toHaveLength(0);
  });

  it("creates a sub-issue under a live parent of its project and announces it", async () => {
    const parent = await makeIssue("Create parent");
    const created = capture("issue.created");

    const child = await makeIssue("Create child", parent.id);

    expect(child.parentId).toBe(parent.id);
    expect(created.map((payload) => payload.issueId)).toEqual([child.id]);
  });

  it("refuses to create under an archived parent, creating nothing", async () => {
    const parent = await makeIssue("Archived before create");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id);
    const created = capture("issue.created");

    await expect(makeIssue("Late child", parent.id)).rejects.toBeInstanceOf(
      AlreadyArchivedError,
    );
    expect(created).toHaveLength(0);
  });
});

describe("listing and roll-up", () => {
  it("lists live direct sub-issues oldest first", async () => {
    const parent = await makeIssue("List parent");
    const first = await makeIssue("List first", parent.id);
    const second = await makeIssue("List second", parent.id);
    const third = await makeIssue("List third", parent.id);
    await makeIssue("List grandchild", second.id);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, second.id);

    const children = await issueService.listSubIssues(
      tenant.actors.member,
      tenant.org.id,
      parent.id,
    );

    expect(children.map((child) => child.id)).toEqual([first.id, third.id]);
  });

  it("rolls up every live issue below at any depth, counting done and canceled as closed", async () => {
    const top = await makeIssue("Roll top");
    const a = await makeIssue("Roll a", top.id);
    const b = await makeIssue("Roll b", top.id);
    const deep = await makeIssue("Roll deep", b.id);
    const gone = await makeIssue("Roll gone", top.id);

    await changeStatus(a.id, "done");
    await changeStatus(b.id, "in_progress");
    await changeStatus(deep.id, "canceled");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, gone.id);

    await expect(
      issueService.getIssueRollup(tenant.actors.member, tenant.org.id, top.id),
    ).resolves.toEqual({ total: 3, open: 1, closed: 2 });
  });

  it("keeps sub-issue reads inside the actor's workspace", async () => {
    const foreign = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Other tree" }),
    );

    await expect(
      issueService.listSubIssues(other.actors.member, tenant.org.id, foreign.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.listSubIssues(tenant.actors.member, tenant.org.id, foreign.id),
    ).rejects.toMatchObject({ code: "not_found" });
    await expect(
      issueService.getIssueRollup(tenant.actors.member, tenant.org.id, foreign.id),
    ).rejects.toMatchObject({ code: "not_found" });
  });
});

describe("archiving takes the sub-issues along", () => {
  it("archives every live issue below, announcing each once, and leaves archived rows as they were", async () => {
    const root = await makeIssue("Tree root");
    const mid = await makeIssue("Tree mid", root.id);
    const leaf = await makeIssue("Tree leaf", mid.id);
    const side = await makeIssue("Tree side", root.id);
    const earlier = await makeIssue("Tree earlier", root.id);
    const alreadyArchived = await issueService.archiveIssue(
      tenant.actors.member,
      tenant.org.id,
      earlier.id,
    );

    const archived = capture("issue.archived");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, root.id);

    expect(archived.map((payload) => payload.issueId).sort()).toEqual(
      [root.id, mid.id, leaf.id, side.id].sort(),
    );
    const untouched = await issueRepo.findIssueById(tenant.org.id, earlier.id);
    expect(untouched?.archivedAt).toBe(alreadyArchived.archivedAt);
  });

  it("leaves the parent live when a sub-issue is archived", async () => {
    const parent = await makeIssue("Survivor parent");
    const child = await makeIssue("Departing child", parent.id);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    expect((await issueRepo.findIssueById(tenant.org.id, parent.id))?.archivedAt).toBeNull();
  });
});

describe("completion notice", () => {
  it("tells the parent's assignee once, when the last open sub-issue closes", async () => {
    const parent = await makeIssue("Notice parent", null, tenant.userIds.admin);
    const first = await makeIssue("Notice first", parent.id);
    const second = await makeIssue("Notice second", parent.id);

    await changeStatus(first.id, "done");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(0);

    await changeStatus(second.id, "canceled");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(1);
  });

  it("tells the assignee again each time the last open sub-issue is closed again", async () => {
    const parent = await makeIssue("Again parent", null, tenant.userIds.admin);
    const child = await makeIssue("Again child", parent.id);

    await changeStatus(child.id, "done");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(1);

    await changeStatus(child.id, "todo");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(1);

    await changeStatus(child.id, "done");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(2);
  });

  it("sends nothing for changes that are not a closing", async () => {
    const parent = await makeIssue("Quiet parent", null, tenant.userIds.admin);
    const open = await makeIssue("Quiet open", parent.id);
    const closed = await issueService.createIssue(
      tenant.actors.member,
      {
        ...issueInput(tenant.org.id, tenant.project.id, { title: "Quiet closed" }),
        status: "done",
        parentId: parent.id,
      },
    );

    await setParent(open.id, null);
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(0);

    await changeStatus(closed.id, "canceled");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(0);

    await changeStatus(closed.id, "todo");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(0);

    await changeStatus(closed.id, "done");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(1);
  });

  it("is sent when the last open sub-issue is archived while open", async () => {
    const parent = await makeIssue("Archive notice parent", null, tenant.userIds.admin);
    const child = await makeIssue("Archive notice child", parent.id);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(1);
  });

  it("does not tell the person who made the change about their own change", async () => {
    const parent = await makeIssue("Own change parent", null, tenant.userIds.member);
    const child = await makeIssue("Own change child", parent.id);

    await changeStatus(child.id, "done");

    expect(await noticesFor(tenant.userIds.member, parent)).toBe(0);
  });

  it("sends nothing when the parent has no assignee", async () => {
    const parent = await makeIssue("Unassigned parent");
    const child = await makeIssue("Unassigned child", parent.id);
    const notices = capture("issue.sub_issues_completed");

    await changeStatus(child.id, "done");

    expect(notices).toHaveLength(0);
  });

  it("looks only at the direct parent, but at every depth below it", async () => {
    const parent = await makeIssue("Direct parent", null, tenant.userIds.admin);
    const child = await makeIssue("Direct child", parent.id, tenant.userIds.viewer);
    const grandchild = await makeIssue("Direct grandchild", child.id);

    // The grandchild is still open below the parent, so the parent hears nothing.
    await changeStatus(child.id, "done");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(0);

    // Closing the grandchild completes the child, whose assignee is told.
    await changeStatus(grandchild.id, "done");
    expect(await noticesFor(tenant.userIds.viewer, child)).toBe(1);
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(0);
  });
});

