    const child = await makeIssue("Create child", parent.id);

    expect(child.parentId).toBe(parent.id);
    expect(created.map((payload) => payload.issueId)).toEqual([child.id]);
  });

  it("refuses to create under an archived parent, creating nothing", async () => {
    const parent = await makeIssue("Archived before create");
