});

describe("archiving takes the sub-issues along", () => {
  it("archives every live issue below, announcing each once, and leaves archived rows as they were", async () => {
    const root = await makeIssue("Tree root");
    const mid = await makeIssue("Tree mid", root.id);
    const leaf = await makeIssue("Tree leaf", mid.id);
    const side = await makeIssue("Tree side", root.id);
    const earlier = await makeIssue("Tree earlier", root.id);
    const alreadyArchived = await issueService.archiveIssue(
      tenant.actors.member,
      tenant.org.id,
      earlier.id,
    );

    const archived = capture("issue.archived");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, root.id);

    expect(archived.map((payload) => payload.issueId).sort()).toEqual(
      [root.id, mid.id, leaf.id, side.id].sort(),
    );
    const untouched = await issueRepo.findIssueById(tenant.org.id, earlier.id);
    expect(untouched?.archivedAt).toBe(alreadyArchived.archivedAt);
  });

  it("leaves the parent live when a sub-issue is archived", async () => {
    const parent = await makeIssue("Survivor parent");
    const child = await makeIssue("Departing child", parent.id);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    expect((await issueRepo.findIssueById(tenant.org.id, parent.id))?.archivedAt).toBeNull();
  });
});

describe("completion notice", () => {
  it("tells the parent's assignee once, when the last open sub-issue closes", async () => {
    const parent = await makeIssue("Notice parent", null, tenant.userIds.admin);
    const first = await makeIssue("Notice first", parent.id);
    const second = await makeIssue("Notice second", parent.id);

    await changeStatus(first.id, "done");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(0);

    await changeStatus(second.id, "canceled");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(1);
  });

  it("tells the assignee again each time the last open sub-issue is closed again", async () => {
    const parent = await makeIssue("Again parent", null, tenant.userIds.admin);
    const child = await makeIssue("Again child", parent.id);

    await changeStatus(child.id, "done");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(1);

    await changeStatus(child.id, "todo");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(1);

    await changeStatus(child.id, "done");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(2);
  });

  it("sends nothing for changes that are not a closing", async () => {
    const parent = await makeIssue("Quiet parent", null, tenant.userIds.admin);
    const open = await makeIssue("Quiet open", parent.id);
    const closed = await issueService.createIssue(
      tenant.actors.member,
      {
        ...issueInput(tenant.org.id, tenant.project.id, { title: "Quiet closed" }),
        status: "done",
        parentId: parent.id,
      },
    );

    await setParent(open.id, null);
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(0);

    await changeStatus(closed.id, "canceled");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(0);

    await changeStatus(closed.id, "todo");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(0);

    await changeStatus(closed.id, "done");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(1);
  });

  it("is sent when the last open sub-issue is archived while open", async () => {
    const parent = await makeIssue("Archive notice parent", null, tenant.userIds.admin);
    const child = await makeIssue("Archive notice child", parent.id);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(1);
  });

  it("does not tell the person who made the change about their own change", async () => {
    const parent = await makeIssue("Own change parent", null, tenant.userIds.member);
    const child = await makeIssue("Own change child", parent.id);

    await changeStatus(child.id, "done");

    expect(await noticesFor(tenant.userIds.member, parent)).toBe(0);
  });

  it("sends nothing when the parent has no assignee", async () => {
    const parent = await makeIssue("Unassigned parent");
    const child = await makeIssue("Unassigned child", parent.id);
    const notices = capture("issue.sub_issues_completed");

    await changeStatus(child.id, "done");

    expect(notices).toHaveLength(0);
  });

  it("looks only at the direct parent, but at every depth below it", async () => {
    const parent = await makeIssue("Direct parent", null, tenant.userIds.admin);
    const child = await makeIssue("Direct child", parent.id, tenant.userIds.viewer);
    const grandchild = await makeIssue("Direct grandchild", child.id);

    // The grandchild is still open below the parent, so the parent hears nothing.
    await changeStatus(child.id, "done");
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(0);

    // Closing the grandchild completes the child, whose assignee is told.
    await changeStatus(grandchild.id, "done");
    expect(await noticesFor(tenant.userIds.viewer, child)).toBe(1);
    expect(await noticesFor(tenant.userIds.admin, parent)).toBe(0);
  });
});

