47	 * permission, a live parent project, a parent (if given) that is live, in the
48	 * same project and within the depth limit, and the plan's per-project issue
49	 * quota. Only then is a number allocated and `issue.created` published —
50	 * everything reactive (notifications, search, webhooks, the audit log) hangs
51	 * off that.
52	 */
53	export async function createIssue(
54	  actor: Actor,
55	  input: CreateIssueInput,
56	): Promise<Issue> {
57	  assertOrgScope(actor, input.orgId);
58	
59	  const project = requireFound(
60	    await projectRepo.findProjectById(input.orgId, input.projectId),
61	    "Project",
62	    input.projectId,
63	  );
64	  assertNotArchived("Project", project.id, project);
65	  assertCan(actor, "issue:create", projectResource(project));
66	
67	  if (input.parentId !== null) {
68	    const parent = await requireParentIssue(input.orgId, project.id, input.parentId);
69	    // The new issue lands one level below its parent, i.e. at the length of the
70	    // parent's lineage (the parent included).
71	    assertWithinDepth(parent.id, (await lineageOf(input.orgId, parent)).length);
72	  }
73	
74	  const org = requireFound(
75	    await orgRepo.findOrgById(input.orgId),
76	    "Organization",
77	    input.orgId,
78	  );
79	  const used = await issueRepo.countIssues(input.orgId, input.projectId);
80	  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
81	    throw new Error(
82	      `Plan ${org.plan} allows no more issues in project ${project.key}`,
83	    );
84	  }
85	
86	  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
87	  const issue = await issueRepo.insertIssue(input, actor.userId, number);
88	
89	  await emit("issue.created", {
90	    ...actorEnvelope(actor),
91	    issueId: issue.id,
92	    projectId: issue.projectId,
93	    title: issue.title,
94	    assigneeId: issue.assigneeId,
95	    priority: issue.priority,
96	  });
97	
98	  return issue;
99	}
