101	export async function updateIssue(
102	  actor: Actor,
103	  input: UpdateIssueInput,
104	): Promise<Issue> {
105	  assertOrgScope(actor, input.orgId);
106	
107	  const before = requireFound(
108	    await issueRepo.findIssueById(input.orgId, input.issueId),
109	    "Issue",
