118	    ...actorEnvelope(actor),
119	    issueId: after.id,
120	    projectId: after.projectId,
121	    changedFields: Object.keys(input).filter(
122	      (key) => key !== "orgId" && key !== "issueId",
123	    ),
124	  });
125	
126	  return after;
127	}
